class Account
    private define balance as integer;

    method constructor(aBalance as integer)
        this.balance <- aBalance;
    endMethod

    public method Balance() as integer
        return this.balance;
    endMethod

    public method Deposit(amount as integer)
        this.balance <- this.balance + amount;
    endMethod
endClass

class SavingsAccount extends Account
    private define rate as integer;

    method constructor(aBalance as integer, aRate as integer)
        super.constructor(aBalance);
        this.rate <- aRate;
    endMethod

    public method ApplyInterest()
        this.Deposit(this.Balance() * this.rate div 100);
    endMethod
endClass

algorithm RunInterest
    define balance as integer;
    define rate as integer;
    define account as SavingsAccount;
    read balance;
    read rate;
    account <- new SavingsAccount(balance, rate);
    account.ApplyInterest();
    write account.Balance();
endAlgorithm
